INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Sicherungskonzept nur für große Unternehmen nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme brauchen Planung"}, {"text": "Ja", "correct": false, "because": "Größe irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für mich bei einem Sicherungskonzept entscheidend?', 3, '[{"text": "Wiederherstellbarkeit", "correct": true, "because": "Ziel ist Datenrettung"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Minimale Kosten", "correct": false, "because": "Zuverlässigkeit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem soliden Konzept?', 5, '[{"text": "Regelmäßige Tests", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Offsite-Speicher", "correct": true, "because": "Schützt vor lokalen Ausfällen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nur Geschwindigkeit"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Konzept braucht einen Plan. b) Es funktioniert ohne Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests sind essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Sicherungskonzept?', 4, '[{"text": "Zeitplan", "correct": false, "because": "Definiert Häufigkeit"}, {"text": "Teststrategie", "correct": false, "because": "Sichert Zuverlässigkeit"}, {"text": "Farbcodierung", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Konzept auch inkrementelle Methoden umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Effiziente Änderungssicherung"}, {"text": "Nein", "correct": false, "because": "Nicht auf Vollbackups beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für ein Konzept mit minimaler Downtime?', 3, '[{"text": "Differenzielle Sicherung", "correct": true, "because": "Schneller als Vollbackup"}, {"text": "Manuelle Kopie", "correct": false, "because": "Zeitaufwendig"}, {"text": "Cloud-Upload", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen machen ein Konzept robust?', 5, '[{"text": "Redundanz", "correct": true, "because": "Mehrere Kopien schützen"}, {"text": "Verschlüsselung", "correct": true, "because": "Sichert Vertraulichkeit"}, {"text": "Hohe Schreibgeschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Konzept braucht Tests. b) Es ist nur für Hardware relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein gutes Sicherungskonzept?', 4, '[{"text": "Regelmäßige Überprüfung", "correct": false, "because": "Sichert Qualität"}, {"text": "Externe Speicherung", "correct": false, "because": "Schützt vor Ausfall"}, {"text": "Detaillierte GUI", "correct": true, "because": "Funktion zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Konzept ohne Planung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Planung ist Kern"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert ineffektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren stärken ein Sicherungskonzept?', 4, '[{"text": "Automatisierte Tests", "correct": true, "because": "Sichern Wiederherstellung"}, {"text": "Multiple Standorte", "correct": true, "because": "Reduzieren Risiko"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Konzept nur Vollbackups braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Inkrementell oft effizienter"}, {"text": "Ja", "correct": false, "because": "Flexibilität wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Sicherungskonzept?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Nutzbarkeit"}, {"text": "Minimale Speichergröße", "correct": false, "because": "Qualität wichtiger"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Planung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Konzept schützt vor Datenverlust. b) Es braucht keine Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern ein Sicherungskonzept?', 5, '[{"text": "Regelmäßige Überprüfung", "correct": true, "because": "Sichert Funktion"}, {"text": "Verschlüsselte Speicherung", "correct": true, "because": "Schützt Daten"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Konzept unwichtig?', 3, '[{"text": "Testplan", "correct": false, "because": "Sichert Erfolg"}, {"text": "Redundanz", "correct": false, "because": "Schützt vor Ausfall"}, {"text": "Design der Oberfläche", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Konzept ohne Tests funktionieren?', 3, '[{"text": "Nein", "correct": true, "because": "Tests prüfen Zuverlässigkeit"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Konzept auch für kleine Datenmengen sinnvoll ist?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz unabhängig von Größe"}, {"text": "Nein", "correct": false, "because": "Auch kleine Daten wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategie wähle ich für ein Konzept mit hoher Sicherheit?', 4, '[{"text": "3-2-1-Regel", "correct": true, "because": "Multiple Kopien, Offsite"}, {"text": "Einmalige Sicherung", "correct": false, "because": "Zu riskant"}, {"text": "Lokale Kopie", "correct": false, "because": "Kein Offsite-Schutz"}]');
